(()=>{const t=document.getElementById("journal-quote");if(!t)return;const n=JSON.parse(t.dataset.quotes);if(!n.length)return;const o="journal-last-movie-quote";let i;try{i=sessionStorage.getItem(o)}catch{}const a=n.filter(e=>e.text!==i),r=a.length?a:n,e=r[Math.floor(Math.random()*r.length)],s=t.querySelector("cite a");t.querySelector("blockquote p").textContent=e.text,t.querySelector("blockquote").setAttribute("cite",e.source),t.querySelector("blockquote").setAttribute("lang",e.lang),s.textContent=e.film,s.href=e.source,s.title=`${e.film} · 台词出处`;try{sessionStorage.setItem(o,e.text)}catch{}})()